from pathlib import Path
import cadquery as cq

PARAMETERS = {"name":"COMPACT_BSPLINE_RULED_LOFT","sections":[{"z":-0.1514305,"points":[[0.004004,-0.0052326],[0.0068771,0.0039238],[0.0045596,0.0166577],[-0.0007782,0.0239258],[-0.0083049,0.0206034],[-0.0097195,0.0110485],[-0.0066963,-0.0013439],[0.0008947,-0.0061673]]},{"z":-0.1223846,"points":[[0.0066245,-0.025667],[0.0135844,-0.0096238],[0.0094224,0.0150321],[0.0054567,0.0331264],[-0.0098624,0.0321671],[-0.0136491,0.0142468],[-0.0098872,-0.0104639],[0.000474,-0.0252177]]},{"z":-0.0933387,"points":[[0.0095386,-0.0355304],[0.014101,-0.0152148],[0.0110943,0.0138389],[0.0076619,0.0351168],[-0.00963,0.0316517],[-0.011759,0.0100143],[-0.0084581,-0.0189491],[0.002548,-0.0359565]]},{"z":-0.0642928,"points":[[0.0064771,-0.0423746],[0.0134589,-0.0213102],[0.0117244,0.0108469],[0.0108804,0.0348906],[-0.0072716,0.0362128],[-0.0115088,0.0125392],[-0.0100016,-0.0196085],[-0.0013107,-0.0411402]]},{"z":-0.0352468,"points":[[0.0073003,-0.0466484],[0.0115328,-0.0223688],[0.0104086,0.0118446],[0.0098422,0.037275],[-0.0088106,0.0335998],[-0.0112173,0.0080554],[-0.0112644,-0.0261492],[-0.0009894,-0.0474561]]},{"z":-0.0062009,"points":[[0.0019487,-0.0493211],[0.0094286,-0.0254875],[0.0099281,0.0096541],[0.0119342,0.0356309],[-0.0075299,0.0373063],[-0.0125043,0.0115203],[-0.0139071,-0.0235592],[-0.0063613,-0.0478491]]},{"z":0.022845,"points":[[0.0015446,-0.0508605],[0.0095772,-0.0268106],[0.0099048,0.0094862],[0.0116028,0.0365339],[-0.0080706,0.0381951],[-0.0135912,0.011581],[-0.0150039,-0.0246366],[-0.0072167,-0.0495774]]},{"z":0.0518909,"points":[[0.0039233,-0.0464441],[0.0100193,-0.0213957],[0.0115034,0.0144637],[0.0130069,0.0408768],[-0.0076606,0.0383244],[-0.0134482,0.0120148],[-0.0151968,-0.0237814],[-0.0047559,-0.0468106]]},{"z":0.0809369,"points":[[0.0037917,-0.0485908],[0.0123981,-0.0246265],[0.0123109,0.0121534],[0.0142011,0.0397522],[-0.0064817,0.0409931],[-0.0140581,0.0141925],[-0.0145031,-0.0211129],[-0.0050114,-0.0464846]]},{"z":0.1099828,"points":[[0.0042849,-0.0399734],[0.0111441,-0.0186117],[0.0171253,0.0112642],[0.0110067,0.0340013],[-0.0078572,0.0361056],[-0.0181111,0.0144203],[-0.0139841,-0.0162472],[-0.0030872,-0.0372299]]},{"z":0.1390287,"points":[[0.0094403,-0.0052752],[0.0147571,0.0023534],[0.0125499,0.0144504],[0.0052925,0.0206402],[-0.0024104,0.0215059],[-0.0040264,0.0121812],[-0.0012687,-5.25e-05],[0.0062493,-0.0050809]]}],"origin":[-0.1977263,-0.8949471,0.0504498],"xdir":[0.058384,0.9038776,-0.4237884],"normal":[0.9786079,-0.135709,-0.1546273],"section_count":11,"points_per_section":8,"section_selection":"uniform endpoints included","point_selection":"uniform cyclic samples","section_curve":"open B-spline + explicit closure","loft_ruled":true}

def build_model():
    p=PARAMETERS; wires=[]
    for sec in p["sections"]:
        plane=cq.Plane(origin=tuple(p["origin"][i]+p["normal"][i]*sec["z"] for i in range(3)), xDir=tuple(p["xdir"]), normal=tuple(p["normal"]))
        wires.append(cq.Workplane(plane).spline([tuple(x) for x in sec["points"]], periodic=False).close().val())
    return cq.Solid.makeLoft(wires, True)

if __name__ == "__main__":
    out=Path(__file__).resolve().parent; t=time.time(); shape=build_model(); valid=bool(shape.isValid())
    cq.exporters.export(shape,str(out/"reconstructed.step")); cq.exporters.export(shape,str(out/"reconstructed.stl"))
    b=shape.BoundingBox(); (out/"geometry.json").write_text(json.dumps(dict(valid=valid,solids=len(shape.Solids()),faces=len(shape.Faces()),bbox=[b.xmin,b.ymin,b.zmin,b.xmax,b.ymax,b.zmax],build_seconds=time.time()-t),indent=2))
    print("VALIDATED",valid,"SOLIDS",len(shape.Solids()),"FACES",len(shape.Faces()),flush=True)
